% Script for running LUKE
%
% This script is automatically generated by irunluke_jd.
% by J. Decker (joan.decker@cea.fr) and Y. Peysson (yves.peysson@cea.fr)
%
clear all
clear mex
clear functions
close all
warning('off','all')
pause(1)
%
% Note : tn is adjusted for a direct comparison with the fluctuation case
%
tn = [94.9783];% Final simulation time (normalized to the central thermal collision time) 
dtn = [100i];% internal LUKE time step. As an imaginary number, dkeparam.dtn prescribes the number of internal time steps
%
% *********************** Specify LUKE structures *****************************
%
locid_simul = '';%Simulation ID
path_simul = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
psin_S = [];%Normalized poloidal flux grid where calculations are performed (0 < psin_S < 1) (If one value: local calculation only, not used if empty)
rho_S = [0:0.1:0.6,0.61:0.01:0.79,0.80:0.05:1];
%
id_dkepath = '';%For all paths used by DKE solver
path_dkepath = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_equil = 'ITER_Scen2_200103121816_430_129';%For plasma equilibrium
path_equil = 'EQUIL/';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_fluct = '';%For fast electron radial transport
path_fluct = 'FLUCT/';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_dkeparam = 'EC_RT';%For DKE code parameters
path_dkeparam = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_dkedisplay = 'NO_DISPLAY';%For output code display
path_dkedisplay = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_ohm = '';%For Ohmic electric contribution
path_ohm = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
ids_wavestruct = {'C3PO_NTM_32_24rays'};%For RF waves contribution (put all the type of waves needed)
paths_wavestruct = {''};%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_transpfaste = '';%For fast electron radial transport
path_transpfaste = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_ripple = '';%For fast electron magnetic ripple losses
path_ripple = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
%************************************************************************************************************************************
%
[dkepath,equil,dkeparam,dkedisplay,ohm,wavestructs,transpfaste,ripple,equil.fluct] = load_structures_yp('dkepath',id_dkepath,path_dkepath,'equil',id_equil,path_equil,'dkeparam',id_dkeparam,path_dkeparam,'dkedisplay',id_dkedisplay,path_dkedisplay,'ohm',id_ohm,path_ohm,'wavestructs',ids_wavestruct,paths_wavestruct,'transpfaste',id_transpfaste,path_transpfaste,'ripple',id_ripple,path_ripple,'fluct',id_fluct,path_fluct);
%
%************************************************************************************************************************************
%
simul.id = make_luke_simulid_jd(equil,ohm,transpfaste,ripple,'',wavestructs,locid_simul);
simul.path = path_simul;
%
dkeparam.timevol = 1;%to calculate time evolution of moments
dkeparam.tn = tn;% as an imaginary number, dkeparam.tn prescribes the number of fluctuation iterations
dkeparam.dtn = dtn;% internal LUKE time step. As an imaginary number, dkeparam.dtn prescribes the number of internal time steps
dkeparam.psin_S = psin_S;
dkeparam.rho_S = rho_S;
%
lukestructs.simul = simul;
lukestructs.equil = equil;
lukestructs.dkeparam = dkeparam;
lukestructs.dkedisplay = dkedisplay;
lukestructs.ohm = ohm;
lukestructs.wavestructs = wavestructs;
lukestructs.transpfaste = transpfaste;
lukestructs.ripple = ripple;
%
lukestructs = run_lukert(lukestructs);
%
% ---------------------------------------------- Save results ----------------------------------------------
%
filename = [path_simul,'LUKE_RESULTS_',simul.id,'.mat'];
save(filename);
info_dke_yp(2,['LUKE Results saved in ',filename]);
%
opt.ir_display = 0;
opt.rho = 'g';
opt.peakmode = 0;
opt.peak = 'n';
opt.wave = 'n';
opt.spec = 0;
opt.diaryname = ['res_',lukestructs.simul.id,'.log'];
%
proc_luke_jd(lukestructs.output,opt);
%



